#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <errno.h>

/* usage: harness <exe> <argv0> [args...]  ; args are hex-decoded */
static char *unhex(const char *s, size_t *outlen) {
    size_t n = strlen(s)/2; char *b = malloc(n+1);
    for (size_t i=0;i<n;i++){ unsigned v; sscanf(s+2*i,"%2x",&v); b[i]=(char)v; }
    b[n]=0; *outlen=n; return b;
}
int main(int argc, char **argv) {
    const char *exe = argv[1];
    size_t l;
    char *a0 = unhex(argv[2], &l);
    char **av = calloc(argc, sizeof(char*));
    av[0] = a0;
    int n = 1;
    for (int i=3;i<argc;i++) av[n++] = unhex(argv[i], &l);
    av[n] = NULL;

    int po[2], pe[2];
    pipe(po); pipe(pe);
    pid_t pid = fork();
    if (pid==0) {
        dup2(po[1],1); dup2(pe[1],2);
        close(po[0]); close(pe[0]); close(po[1]); close(pe[1]);
        execv(exe, av);
        _exit(127);
    }
    close(po[1]); close(pe[1]);
    char *ob=malloc(1<<20), *eb=malloc(1<<20); size_t ol=0, el=0; ssize_t r;
    while ((r=read(po[0],ob+ol,(1<<20)-ol))>0) ol+=r;
    while ((r=read(pe[0],eb+el,(1<<20)-el))>0) el+=r;
    int st; waitpid(pid,&st,0);
    printf("STATUS=0x%04x EXIT=%d SIG=%d OUTLEN=%zu ERRLEN=%zu\n", st,
        WIFEXITED(st)?WEXITSTATUS(st):-1, WIFSIGNALED(st)?WTERMSIG(st):0, ol, el);
    printf("STDOUT<<");
    for (size_t i=0;i<ol;i++) { unsigned char c=ob[i]; if (c>=32&&c<127) putchar(c); else printf("\\x%02x",c); }
    printf(">>\n");
    printf("STDERR<<");
    for (size_t i=0;i<el && i<400;i++) { unsigned char c=eb[i]; if (c>=32&&c<127) putchar(c); else printf("\\x%02x",c); }
    printf(">>\n");
    return 0;
}
EOF
